"""WSClient — WebSocket 客户端，出站连接平台。

核心职责：
- 出站连接到平台 WS Server（穿透 NAT）
- 断线自动重连（指数退避）
- Token 认证（通过 URL 参数或子协议头）
- 心跳保活（websockets 库内建 ping/pong）
- 上行消息发送（send 方法）
- 下行消息接收与路由（recv loop → handlers.dispatch）
"""
import asyncio
import json
import logging
import signal
import time

import websockets
import websockets.exceptions

from agent_runtime.ws import protocol
from agent_runtime.ws.reconnect import ReconnectStrategy

logger = logging.getLogger("agent.ws.client")


class WSClient:
    """WebSocket 客户端 — 出站连接平台。

    用法:
        client = WSClient(config, handlers)
        asyncio.run(client.run_forever())
    """

    def __init__(self, config, handlers):
        """
        参数:
            config: RuntimeConfig 实例
            handlers: MessageHandlers 实例
        """
        self.config = config
        self.handlers = handlers
        self.app = None  # AgentApp 引用，由外部设置，用于连接后发送完整状态注册
        self.strategy = ReconnectStrategy(
            base_delay=config.get('ws_reconnect_base', 1),
            max_delay=config.get('ws_reconnect_max', 60))
        self._ws = None
        self._running = False
        self._send_queue = None  # asyncio.Queue, 在 run_forever 中初始化
        self._connected_at = None
        self._loop = None  # asyncio 事件循环引用，在 run_forever 中设置
        self._loop_callback = None  # loop 就绪后的回调（用于通知 MonitorReporter 更新 loop）

    @property
    def connected(self):
        return self._ws is not None and self._connected_at is not None

    @property
    def loop(self):
        """获取 WS 客户端的事件循环（供同步线程调度异步发送）。"""
        return self._loop

    @property
    def ws_url(self):
        """构造 WS 连接 URL。"""
        base = self.config.ws_url
        if not base:
            # 从 backend_url 推导
            backend = self.config.backend_url
            if not backend:
                return ''
            # http(s) → ws(s)
            ws_base = backend.replace('https://', 'wss://') \
                               .replace('http://', 'ws://')
            base = ws_base
        agent_id = self.config.agent_id
        return '%s/ws/agent/%s/' % (base.rstrip('/'), agent_id)

    @property
    def ws_extra_headers(self):
        """构造认证头。"""
        headers = {}
        token = self.config.ws_token
        if token:
            headers['Authorization'] = 'Bearer %s' % token
            logger.debug('WS 认证头已设置: token=%s...', token[:10] if len(token) > 10 else token)
        else:
            logger.warning('WS 认证头未设置: ws_token 为空!')
        return headers

    async def run_forever(self):
        """主循环：连接 → 收发消息 → 断线重连。"""
        self._running = True
        self._send_queue = asyncio.Queue(maxsize=256)
        self._loop = asyncio.get_running_loop()  # 保存事件循环引用，供同步线程调度异步发送

        # 通知外部组件（如 MonitorReporter）事件循环已就绪
        if self._loop_callback:
            try:
                self._loop_callback(self._loop)
            except Exception:
                logger.warning('loop 回调执行失败', exc_info=True)

        while self._running:
            url = self.ws_url
            if not url:
                logger.error('未配置 AGENT_WS_URL 或 CHIIP_BACKEND_URL，'
                             '无法建立 WebSocket 连接')
                await asyncio.sleep(30)
                continue

            try:
                logger.info('正在连接: %s', url)
                async with websockets.connect(
                    url,
                    additional_headers=self.ws_extra_headers,
                    ping_interval=self.config.get('ws_ping_interval', 30),
                    ping_timeout=self.config.get('ws_ping_timeout', 10),
                    close_timeout=5,
                ) as ws:
                    self._ws = ws
                    self._connected_at = time.time()
                    self.strategy.reset()
                    logger.info('WebSocket 已连接: %s', url)

                    # 连接后发送注册消息
                    await self._on_connected()

                    # 并行：收消息 + 发消息 + 周期心跳
                    recv_task = asyncio.create_task(
                        self._recv_loop(ws))
                    send_task = asyncio.create_task(
                        self._send_loop(ws))
                    heartbeat_task = asyncio.create_task(
                        self._periodic_heartbeat())

                    # 任一任务结束（通常是断线）则取消其他
                    done, pending = await asyncio.wait(
                        [recv_task, send_task, heartbeat_task],
                        return_when=asyncio.FIRST_COMPLETED)
                    for task in pending:
                        task.cancel()
                        try:
                            await task
                        except asyncio.CancelledError:
                            pass

            except (websockets.exceptions.ConnectionClosed,
                    websockets.exceptions.InvalidStatusCode,
                    OSError) as e:
                logger.warning('WebSocket 连接断开: %s', e)
            except Exception:
                logger.exception('WebSocket 未知异常')
            finally:
                self._ws = None
                self._connected_at = None

            if not self._running:
                break

            # 断线重连等待
            delay = await self.strategy.async_wait()
            logger.info('将在 %.1fs 后重连...', delay)

    async def _periodic_heartbeat(self):
        """周期性心跳：定时向平台发送包含 runtime_mode 的状态心跳。

        作为模式切换通知的兑底机制，确保即使即时通知失败，
        平台也能在下一个心跳周期内同步到正确的运行模式。
        """
        interval = self.config.get('heartbeat_interval', 10)
        while self._running and self._ws:
            try:
                await asyncio.sleep(interval)
                if not self._ws:
                    break
                status_data = {}
                if self.app:
                    try:
                        status_data = self.app.status_snapshot()
                    except Exception:
                        pass
                status_data['runtime_mode'] = getattr(
                    self.config, 'run_mode', 'local')
                msg = protocol.make_heartbeat(
                    self.config.agent_id, status=status_data)
                await self.send(msg)
                logger.debug('周期心跳已发送: mode=%s',
                             status_data.get('runtime_mode', '?'))
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.warning('周期心跳发送失败', exc_info=True)

    async def _on_connected(self):
        """连接成功后发送注册消息 + 完整状态心跳。

        约束 3（模式切换状态一致性）：
        WS 连接建立后立即发送完整状态注册消息（包含当前模式、在线状态、系统信息），
        消除平台端状态空白期。
        """
        try:
            card_data = {}
            card_file = self.config.agent_card_file
            if card_file.exists():
                try:
                    card_data = json.loads(
                        card_file.read_text(encoding='utf-8'))
                except (ValueError, OSError):
                    pass

            # 1. 发送能力注册消息
            register_msg = protocol.make_register(
                self.config.agent_id, card_data)
            await self._ws.send(protocol.encode(register_msg))
            logger.info('注册消息已发送')

            # 2. 立即发送完整状态心跳（消除模式切换后的状态空白期）
            # 约束 2（本地模式行为修正）：仅在 collaborative/order 模式下发送
            # （本地模式下 WS 根本不会连接，此处天然满足）
            status_data = {}
            if self.app:
                try:
                    status_data = self.app.status_snapshot()
                except Exception:
                    logger.warning('获取状态快照失败', exc_info=True)
            status_data['runtime_mode'] = getattr(
                self.config, 'run_mode', 'local')

            heartbeat_msg = protocol.make_heartbeat(
                self.config.agent_id, status=status_data)
            await self._ws.send(protocol.encode(heartbeat_msg))
            logger.info('完整状态注册心跳已发送: mode=%s',
                        status_data.get('runtime_mode', '?'))
        except Exception:
            logger.exception('发送注册消息失败')

    async def _recv_loop(self, ws):
        """接收循环：解析下行消息并路由到处理器。"""
        try:
            async for raw in ws:
                msg_type, payload = protocol.parse_message(raw)
                logger.debug('收到消息: type=%s', msg_type)
                await self.handlers.dispatch(msg_type, payload)
        except websockets.exceptions.ConnectionClosed:
            raise  # 让外层处理重连
        except Exception:
            logger.exception('接收消息异常')

    async def _send_loop(self, ws):
        """发送循环：从队列取消息发送。"""
        try:
            while True:
                msg = await self._send_queue.get()
                try:
                    raw = protocol.encode(msg) if isinstance(
                        msg, dict) else msg
                    await ws.send(raw)
                except websockets.exceptions.ConnectionClosed:
                    raise
                except Exception:
                    logger.exception('发送消息失败')
        except websockets.exceptions.ConnectionClosed:
            raise
        except asyncio.CancelledError:
            raise

    async def send(self, msg):
        """发送一条消息（仅限 WS 事件循环内调用）。

        ⚠ 本方法只能在 WS 自身的事件循环内调用。跨线程/跨循环请用
          send_threadsafe() 或 send_now()：asyncio.Queue 非线程安全，
          跨循环 put_nowait 会入队但不会唤醒目标循环。

        如果未连接或队列已满，消息会被丢弃并记录警告。
        """
        if self._send_queue is None:
            logger.warning('WS 客户端未启动，消息丢弃: type=%s',
                           msg.get('type', '?'))
            return
        try:
            self._send_queue.put_nowait(msg)
        except asyncio.QueueFull:
            logger.warning('发送队列已满（%d），消息丢弃: type=%s',
                           self._send_queue.maxsize,
                           msg.get('type', '?'))

    async def send_now(self, msg):
        """在 WS 事件循环内直接发送（绕过发送队列）。

        用于需要投递确认的场景（如模式切换通知）：配合
        run_coroutine_threadsafe 可以 await 到真正发出的时刻，
        避免消息还在队列里就被关连接。
        """
        if self._ws is None:
            logger.warning('WS 未连接，消息丢弃: type=%s',
                           msg.get('type', '?') if isinstance(msg, dict) else '?')
            return
        raw = protocol.encode(msg) if isinstance(msg, dict) else msg
        await self._ws.send(raw)

    def send_threadsafe(self, msg):
        """从其他线程/事件循环安全地投递消息（不阻塞）。

        ★ 关键: asyncio.Queue 非线程安全。跨循环直接 put_nowait 虽然会把
          消息放进内部 deque，但唤醒消费者的 future 是通过 loop.call_soon
          触发的（不写 self-pipe），目标循环不会被唤醒，消息会滞留到
          下一次循环因其他原因苏醒（ping / 周期心跳，可达数十秒）。
          call_soon_threadsafe 会写 self-pipe，立即唤醒目标循环。

        返回: bool，是否成功投递。
        """
        loop = self._loop
        if loop is None or self._send_queue is None:
            logger.warning('WS 未就绪，消息丢弃: type=%s',
                           msg.get('type', '?') if isinstance(msg, dict) else '?')
            return False
        try:
            loop.call_soon_threadsafe(self._send_queue.put_nowait, msg)
            return True
        except RuntimeError:
            logger.warning('WS 事件循环已关闭，消息丢弃')
            return False
        except asyncio.QueueFull:
            logger.warning('发送队列已满，消息丢弃')
            return False

    def stop(self):
        """停止客户端（可从其他线程调用）。"""
        self._running = False
        ws, loop = self._ws, self._loop
        if ws is not None and loop is not None:
            # 不能用 asyncio.create_task: 本方法常从 FastAPI 线程调用，
            # 该线程无运行中的 WS 循环，会抛 RuntimeError 导致连接未关闭
            try:
                asyncio.run_coroutine_threadsafe(ws.close(), loop)
            except Exception as e:
                logger.warning('关闭 WS 连接失败: %s', e)
